create table if not exists domains(id text primary key, canonical_hostname text not null unique, created_at timestamptz not null default now());
create table if not exists domain_aliases(id text primary key, domain_id text not null references domains(id) on delete cascade, original_observed_name text not null, normalization_status text not null, normalization_reason text);
create table if not exists data_sources(id text primary key, name text not null unique, status text not null default 'HEALTHY', last_success timestamptz, last_failure timestamptz, last_error text, rate_limit_state text, version text);
create table if not exists source_events(id text primary key, source_id text references data_sources(id), source_event_id text, observed_at timestamptz not null, payload jsonb not null default '{}');
create table if not exists discovery_events(id text primary key, domain_id text references domains(id), source text not null, source_event_id text, first_seen timestamptz not null, last_seen timestamptz not null, source_confidence double precision);
create table if not exists candidates(id text primary key, hostname text not null unique, original_name text not null, source text not null, first_seen timestamptz not null, last_seen timestamptz not null);
create table if not exists dns_records(id text primary key, candidate_id text references candidates(id) on delete cascade, record_type text not null, value text not null, ttl integer, observed_at timestamptz not null);
create table if not exists dns_observations(id text primary key, candidate_id text references candidates(id) on delete cascade, resolver text, resolver_type text, status text not null, observed_at timestamptz not null, payload jsonb not null default '{}');
create table if not exists ip_addresses(id text primary key, ip inet not null unique, address_family text not null, classification text not null);
create table if not exists ip_observations(id text primary key, candidate_id text references candidates(id) on delete cascade, ip_id text references ip_addresses(id), observed_at timestamptz not null, payload jsonb not null default '{}');
create table if not exists certificates(id text primary key, fingerprint text not null unique, serial text, issuer text, subject text, not_before timestamptz, not_after timestamptz, signature_algorithm text, public_key_algorithm text, key_size integer, ct_log text, first_seen timestamptz, last_seen timestamptz);
create table if not exists certificate_names(id text primary key, certificate_id text references certificates(id) on delete cascade, dns_name text not null, wildcard boolean not null default false);
create table if not exists asn_records(id text primary key, ip_id text references ip_addresses(id), asn text, organization text, network text, provider text, source text, confidence double precision, observed_at timestamptz not null);
create table if not exists geo_records(id text primary key, ip_id text references ip_addresses(id), country text, region text, city text, latitude double precision, longitude double precision, datacenter text, source text, confidence double precision, observed_at timestamptz not null);
create table if not exists tcp_tls_observations(id text not null, candidate_id text not null references candidates(id) on delete cascade, origin text not null, probe_id text, measured_at timestamptz not null, resolved_ip inet, address_family text, dns_status text, tcp_result text, tcp_connect_ms double precision, tls_result text, tls_handshake_ms double precision, total_connection_ms double precision, tls_version text, cipher text, alpn text, sni_accepted boolean not null default false, cert_hostname_valid boolean not null default false, cert_chain_valid boolean not null default false, cert_fingerprint text, cert_issuer text, cert_subject text, error_code text, extra jsonb not null default '{}', primary key(id, measured_at)) partition by range(measured_at);
create table if not exists tcp_tls_observations_default partition of tcp_tls_observations default;
create index if not exists idx_tcp_tls_candidate_time on tcp_tls_observations(candidate_id, measured_at desc);
create index if not exists idx_tcp_tls_ip_time on tcp_tls_observations(resolved_ip, measured_at desc);
create table if not exists http_observations(id text primary key, candidate_id text references candidates(id) on delete cascade, measured_at timestamptz not null, status_code integer, protocol text, server_header text, redirect_location text, redirect_count integer, response_ms double precision, content_length bigint, content_type text, hsts boolean, error_code text);
create table if not exists latency_measurements(id text primary key, candidate_id text references candidates(id) on delete cascade, origin text not null, sample_count integer not null, successful_samples integer not null, failed_samples integer not null, min_rtt_ms double precision, median_rtt_ms double precision, mean_rtt_ms double precision, p95_rtt_ms double precision, jitter_ms double precision, packet_loss double precision, tcp_connect_ms double precision, tls_handshake_ms double precision, total_request_ms double precision, measured_at timestamptz not null);
create table if not exists probe_locations(id text primary key, probe_id text not null unique, probe_type text, country text, city text, asn text, provider text, latitude double precision, longitude double precision, observed_at timestamptz);
create table if not exists probes(id text primary key, status text not null, last_seen timestamptz, version text, capabilities jsonb not null default '{}', country text, city text, asn text, provider text);
create table if not exists probe_runs(id text primary key, probe_id text references probes(id), candidate_id text references candidates(id), started_at timestamptz, completed_at timestamptz, status text, payload jsonb not null default '{}');
create table if not exists reality_tests(id text primary key, candidate_id text references candidates(id), status text not null, xray_version text, transport text, handshake_result text, failure_reason text, evidence jsonb not null default '{}', tested_at timestamptz);
create table if not exists scans(id text primary key, input jsonb not null, mode text not null, profile text not null, top_n integer not null, sample_count integer not null, status text not null, created_at timestamptz not null default now(), completed_at timestamptz);
create table if not exists scan_jobs(id text primary key, scan_id text not null references scans(id) on delete cascade, job_type text not null, status text not null, priority integer not null default 0, attempt integer not null default 0, max_attempts integer not null default 3, created_at timestamptz not null default now(), started_at timestamptz, completed_at timestamptz, worker_id text, error_code text, error_message text);
create index if not exists idx_scan_jobs_pending on scan_jobs(status, created_at) where status='PENDING';
create table if not exists scan_stage_runs(id text primary key, scan_id text references scans(id) on delete cascade, stage text not null, started_at timestamptz, completed_at timestamptz, duration_ms double precision, candidate_count integer, success_count integer, failure_count integer, status text);
create table if not exists score_snapshots(id text primary key, scan_id text references scans(id) on delete cascade, candidate_id text references candidates(id) on delete cascade, final_score double precision, confidence text, explanation jsonb, score_version text not null, generated_at timestamptz not null);
create index if not exists idx_score_snapshots_scan_score on score_snapshots(scan_id, final_score desc);
create table if not exists scan_results(scan_id text references scans(id) on delete cascade, candidate_id text references candidates(id) on delete cascade, rank integer not null, sni text not null, target text not null, median_rtt_ms double precision, p95_rtt_ms double precision, stability double precision, score double precision, confidence text, freshness double precision, tls text, alpn text, ipv4 text, ipv6 text, explanation jsonb, last_checked timestamptz, primary key(scan_id,candidate_id));
create table if not exists change_events(id text primary key, candidate_id text references candidates(id), type text not null, previous jsonb, current jsonb, observed_at timestamptz not null);
create table if not exists audit_logs(id text primary key, actor text, action text not null, request_id text, scan_id text, payload jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists api_tokens(id text primary key, token_hash text not null unique, label text, created_at timestamptz not null default now(), revoked_at timestamptz);
create table if not exists users(id text primary key, username text not null unique, password_hash text, role text not null);
create table if not exists settings(key text primary key, value jsonb not null);
